namespace al {
bool validAdjacency(const RepoRuntime& r,const LevelData& l,int layer){if(size_t(layer)>=l.layers.size())return false;for(size_t i=0;i<l.layers[layer].blocks.size();i++){int a=r.byHash(l.layers[layer].blocks[i]);if(a<0)return false;for(int d=3;d<6;d++){auto p=position(i,l.size)+delta[d];if(inside(p,l.size)&&!r.compatible(a,d,r.byHash(l.layers[layer].blocks[index(p,l.size)])))return false;}}return true;}
Quality quality(const RepoRuntime& r,const LevelData& l){Quality out;if(l.layers.empty())return out;auto& cells=l.layers[0].blocks;std::vector<int> state(cells.size());std::vector<uint8_t> seen(cells.size());auto walk=[&](int s){return s>=0&&r.states[s].group>=2&&r.states[s].walkable;};auto open=[&](Id id){return std::find(r.source.closedSideIds.begin(),r.source.closedSideIds.end(),id)==r.source.closedSideIds.end();};for(size_t i=0;i<cells.size();i++)state[i]=r.byHash(cells[i]);for(size_t i=0;i<cells.size();i++)if(!seen[i]&&walk(state[i])){std::vector<size_t> component{i};seen[i]=1;for(size_t head=0;head<component.size();head++){auto c=component[head];for(int d=0;d<6;d++){auto p=position(c,l.size)+delta[d];if(!inside(p,l.size))continue;auto n=index(p,l.size);if(!seen[n]&&walk(state[n])&&(r.states[state[c]].walkableSides&(1<<d))&&(r.states[state[n]].walkableSides&(1<<opposite(d)))&&open(r.states[state[c]].baseIds[d])&&r.compatible(state[c],d,state[n])){seen[n]=1;component.push_back(n);}}}if(component.size()>out.component.size())out.component=std::move(component);}
 out.walkable=int(out.component.size());out.coverage=cells.empty()?0:double(out.walkable)/cells.size();std::set<int> floors;std::set<std::pair<std::string,Int3>,bool(*)(const std::pair<std::string,Int3>&,const std::pair<std::string,Int3>&)> bigs(+[](const std::pair<std::string,Int3>& a,const std::pair<std::string,Int3>& b){return std::tie(a.first,a.second.x,a.second.y,a.second.z)<std::tie(b.first,b.second.x,b.second.y,b.second.z);});
 for(auto c:out.component){auto p=position(c,l.size);floors.insert(p.z);auto& s=r.states[state[c]];if(r.groups[s.group]=="Corridors")out.corridors++;if(!s.bigBlockUid.empty()){auto p0=p;Vec3 part=vec(s.bigBlockCell);for(auto a:s.groupActions)part=linear(part,a);for(int a=0;a<3;a++)p0[a]-=int(std::lround(part[a]));bigs.insert({s.bigBlockUid,p0});}}
 out.floors=floors.size();for(auto p:bigs)for(auto& b:r.source.bigBlocks)if(b.uid==p.first){if(b.name.find("stair")!=b.name.npos){out.verticalLinks++;}if(b.name.find("atrium")!=b.name.npos){out.atria++;out.verticalLinks++;}if(b.name.find("hall")!=b.name.npos)out.halls++;}return out;}
namespace solver {
struct Failure:std::runtime_error{Int3 cell;std::string stage;Failure(Int3 p,std::string s):std::runtime_error(s),cell(p),stage(std::move(s)){} };
class Attempt {
 const SolveRequest& q;const RepoRuntime& r;int start,n;Int3 size;size_t cells,words;std::vector<uint64_t> wave;std::vector<uint16_t> support;std::vector<int> counts,singleCounter;std::vector<double> weights,sums;double totalWeight=0;std::vector<std::pair<int,int>> stack;
 struct Event {uint32_t index;uint8_t kind;};std::vector<Event> journal;
 struct Decision {size_t mark;int cell,state;};std::vector<Decision> decisions;
 std::array<std::vector<std::vector<int>>,6> connections;std::vector<std::array<int,6>> neighbors;std::mt19937 rng;std::chrono::steady_clock::time_point began;uint64_t operations=0;int backtracks=0;Int3 contradiction{};std::string stage="Fill";
 bool has(int c,int s)const{return wave[size_t(c)*words+s/64]&(1ull<<(s%64));}
 void bit(int c,int s,bool on){auto& w=wave[size_t(c)*words+s/64];if(on)w|=1ull<<(s%64);else w&=~(1ull<<(s%64));}
 int only(int c)const{for(int s=0;s<n;s++)if(has(c,s))return s;return -1;}
 Int3 point(int c)const{return position(c,size)+q.bounds.min;}
 void check(){if((++operations&127)!=0)return;if(q.cancel&&q.cancel->load())throw Failure(point(0),"cancelled");if(journal.size()>2000000||backtracks>2048||std::chrono::duration<double>(std::chrono::steady_clock::now()-began).count()>4)throw Failure(contradiction,"iteration budget exceeded");}
 void event(uint8_t kind,uint32_t i){journal.push_back({i,kind});check();}
 bool ban(int c,int s){if(!has(c,s))return counts[c]!=0;if(counts[c]==1)singleCounter[s]--;event(0,uint32_t(c*n+s));bit(c,s,false);counts[c]--;sums[c]-=weights[s];if(counts[c]==1)singleCounter[only(c)]++;stack.push_back({c,s});if(!counts[c]){contradiction=point(c);return false;}return true;}
 bool propagate(){bool good=true;while(!stack.empty()){auto [c,s]=stack.back();stack.pop_back();for(int d=0;d<6;d++){int nc=neighbors[c][d];if(nc<0)continue;for(int k:connections[d][s])if(has(nc,k)){auto si=(size_t(nc)*n+k)*6+opposite(d);if(!support[si])continue;event(1,uint32_t(si));if(--support[si]==0)good=ban(nc,k)&&good;}}}return good;}
 void undo(size_t mark){stack.clear();while(journal.size()>mark){auto e=journal.back();journal.pop_back();if(e.kind==1){support[e.index]++;continue;}int c=e.index/n,s=e.index%n;if(counts[c]==1)singleCounter[only(c)]--;bit(c,s,true);counts[c]++;sums[c]+=weights[s];if(counts[c]==1)singleCounter[only(c)]++;}}
 double random(){return (rng()>>8)*(1.0/16777216.0);}
 int pickCell(){int chosen=-1;double best=1e300;int pending=0;for(size_t c=0;c<cells;c++)if(counts[c]>1){if(q.cellPick==CellPick::RandomOrder){if(random()*++pending<1)chosen=int(c);}else{double w=0,wl=0;for(int s=0;s<n;s++)if(has(c,s)){double a=std::max(weights[s],1e-6);w+=a;wl+=a*std::log(a);}double score=q.cellPick==CellPick::MinWeightSum?std::log(w)+1e-4*random():std::log(w)-wl/w+1e-6*random();if(score<best){best=score;chosen=c;}}}return chosen;}
 int pickState(int c){std::vector<int> candidates,preferred;double total=0;for(int s=0;s<n;s++)if(has(c,s)){candidates.push_back(s);if((singleCounter[s]+1.)/cells<weights[s]/std::max(totalWeight,1e-30))preferred.push_back(s);}if(!preferred.empty())candidates=preferred;for(int s:candidates)total+=weights[s];if(total<=0)return candidates[std::min(size_t(random()*candidates.size()),candidates.size()-1)];double t=random()*total;for(int s:candidates)if((t-=weights[s])<0)return s;return candidates.back();}
 bool collapse(int c,int chosen){bool good=true;for(int s=0;s<n;s++)if(s!=chosen&&has(c,s))good=ban(c,s)&&good;return good&&propagate();}
 BoundaryValue interior(Int3 p,int d){auto n=p+delta[d];size_t i=index(n,q.level->size);auto h=q.level->layers[q.layer].blocks[i];if(h)return {BoundaryValue::Block,h,0};if(q.layer==0&&q.inputWave&&i<q.inputWave->size())return {BoundaryValue::Group,0,uint32_t((*q.inputWave)[i].groups)};return {};}
 bool matches(int s,int d,BoundaryValue b){if(b.kind==BoundaryValue::Nothing)return true;if(b.kind==BoundaryValue::Block){int other=r.byHash(b.hash);if(other<0)throw Failure(contradiction,"boundary builder uses a different repo");return r.compatible(start+s,d,other);}for(int k:connections[d][s])if(b.mask&(1u<<r.states[start+k].group))return true;return false;}
public:
 Attempt(const SolveRequest& request,uint32_t seed):q(request),r(*request.repo),start(r.layerRange[q.layer].begin),n(r.layerRange[q.layer].end-start),size(q.bounds.size()),cells(volume(size)),words((n+63)/64),rng(seed),began(std::chrono::steady_clock::now()){
  if(cells*size_t(n)*6*sizeof(uint16_t)>512ull*1024*1024)throw Failure({},"solver support memory exceeds 512 MiB; reduce bounds or library");wave.assign(cells*words,0);support.assign(cells*n*6,0);counts.assign(cells,0);sums.assign(cells,0);singleCounter.assign(n,0);weights.resize(n);neighbors.resize(cells);
  for(int s=0;s<n;s++){weights[s]=r.states[start+s].weight;int group=r.states[start+s].weightGroup;if(size_t(group)<q.weightOverride.size()&&q.weightOverride[group]>=0)weights[s]=q.weightOverride[group];auto multiplier=q.moduleWeightMultipliers.find(r.states[start+s].bigBlockUid.empty()?r.states[start+s].blockUid:r.states[start+s].bigBlockUid);if(multiplier!=q.moduleWeightMultipliers.end()){if(!std::isfinite(multiplier->second)||multiplier->second<0||multiplier->second>1e6)throw std::runtime_error("invalid module weight multiplier");weights[s]*=multiplier->second;}totalWeight+=weights[s];for(int d=0;d<6;d++){if(connections[d].empty())connections[d].resize(n);for(int k:r.conn[d][start+s])connections[d][s].push_back(k-start);}}
 }
 std::vector<uint64_t> run(){
  stage="Fill";for(size_t c=0;c<cells;c++){check();auto p=point(c);size_t li=index(p,q.level->size);std::vector<int> upper;if(q.layer>0){int lower=r.byHash(q.level->layers[q.layer-1].blocks[li]);if(lower<0)throw Failure(p,"lower layer must be fully built");upper=r.upperOf(lower);}uint32_t mask=q.inputWave&&li<q.inputWave->size()?uint32_t((*q.inputWave)[li].groups):INT32_MAX;
   for(int s=0;s<n;s++)if(q.layer>0?std::find(upper.begin(),upper.end(),start+s)!=upper.end():(mask&(1u<<r.states[start+s].group))!=0){bit(c,s,true);counts[c]++;sums[c]+=weights[s];}if(!counts[c])throw Failure(p,stage);if(counts[c]==1)singleCounter[only(c)]++;for(int d=0;d<6;d++){auto p=position(c,size)+delta[d];neighbors[c][d]=inside(p,size)?int(index(p,size)):-1;}}
  for(size_t c=0;c<cells;c++)for(int s=0;s<n;s++)if(has(c,s))for(int d=0;d<6;d++){check();int nc=neighbors[c][d];uint16_t count=nc<0?1:0;if(nc>=0)for(int k:connections[d][s])count+=has(nc,k);support[(c*n+s)*6+d]=count;}
  bool good=true;for(size_t c=0;c<cells;c++)for(int s=0;s<n;s++)if(has(c,s))for(int d=0;d<6;d++)if(!support[(c*n+s)*6+d]){good=ban(c,s)&&good;break;}
  for(int pass=0;pass<2;pass++){stage=pass?"Exterior boundary":"Interior boundary";for(size_t c=0;c<cells;c++){auto p=point(c);for(int d=0;d<6;d++)if(neighbors[c][d]<0){auto np=p+delta[d];bool internal=inside(np,q.level->size);if(internal!=(pass==0))continue;BoundaryValue value=internal?interior(p,d):(q.boundaries[d]?q.boundaries[d]->evaluate(np+q.level->position,q.layer):BoundaryValue{});for(int s=0;s<n;s++)if(has(c,s)&&!matches(s,d,value))good=ban(c,s)&&good;}}}
  stage="Propagate";good=propagate()&&good;if(!good)throw Failure(contradiction,stage);journal.clear();
  for(;;){check();if(q.progress){int solved=0;for(int n:counts)solved+=n==1;q.progress->store(float(solved)/cells);}int c=pickCell();if(c<0)break;int s=pickState(c);decisions.push_back({journal.size(),c,s});stage="Observe";good=collapse(c,s);while(!good){if(decisions.empty())throw Failure(contradiction,"Propagate");auto choice=decisions.back();decisions.pop_back();undo(choice.mark);backtracks++;good=ban(choice.cell,choice.state)&&propagate();}}
  std::vector<uint64_t> result(cells);for(size_t c=0;c<cells;c++)result[c]=r.states[start+only(c)].hash;return result;
 }
 int backtrackCount()const{return backtracks;}
};
struct One {SolveResult info;LevelData level;bool success=false;};
static bool prune(const RepoRuntime& r,LevelData& l,const Quality& q){std::vector<uint8_t> kept(volume(l.size));for(auto c:q.component)kept[c]=1;auto old=l;for(size_t c=0;c<kept.size();c++)if(!kept[c]){int s=r.byHash(l.layers[0].blocks[c]);if(s<0||r.states[s].group<2||!r.states[s].walkable)continue;bool replaced=false;for(int g=0;g<2&&!replaced;g++){int candidate=r.builtin(0,g);bool good=true;for(int d=0;d<6;d++){auto np=position(c,l.size)+delta[d];if(!inside(np,l.size))continue;size_t nc=index(np,l.size);if(!kept[nc])continue;good&=r.compatible(candidate,d,r.byHash(l.layers[0].blocks[nc]));}if(good){l.layers[0].blocks[c]=r.states[candidate].hash;replaced=true;}}if(!replaced){l=old;return false;}}
 if(!validAdjacency(r,l,0)){l=old;return false;}return true;}
static One attempt(const SolveRequest& q,uint32_t seed){One out;out.level=*q.level;auto begin=std::chrono::steady_clock::now();try{Attempt solver(q,seed);auto cells=solver.run();for(size_t i=0;i<cells.size();i++){auto p=position(i,q.bounds.size())+q.bounds.min;out.level.layers[q.layer].blocks[index(p,out.level.size)]=cells[i];}bool full=q.bounds.min==Int3{}&&q.bounds.max==out.level.size;out.level.layers[q.layer].valid=full||q.level->layers[q.layer].valid;out.info.backtracks=solver.backtrackCount();out.info.quality=quality(*q.repo,out.level);if(full&&q.layer==0){bool pruned=!q.keepLargestComponent||prune(*q.repo,out.level,out.info.quality);out.info.quality=quality(*q.repo,out.level);out.info.accepted=pruned&&out.info.quality.coverage+1e-9>=q.minCoverage&&(!q.requireAllFloors||out.info.quality.floors==out.level.size.z);}else out.info.accepted=true;out.success=true;}catch(const Failure& f){out.info.failCell=f.cell;out.info.failStage=f.stage;}out.info.seedUsed=seed;out.info.ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();return out;}
}
SolveResult solve(SolveRequest& q){if(!q.repo||!q.level)throw std::runtime_error("The Repo isn't assigned!");if(q.layer<0||size_t(q.layer)>=q.repo->layerRange.size()||size_t(q.layer)>=q.level->layers.size())throw std::runtime_error("invalid layer index");if(q.layer>0&&!q.level->layers[q.layer-1].valid)throw std::runtime_error("you need to build the layer fully before editing upper layer!");if(volume(q.bounds.size())==0||!q.bounds.contains(q.bounds.min)||!inside(q.bounds.min,q.level->size)||!inside(q.bounds.max-Int3{1,1,1},q.level->size))throw std::runtime_error("invalid solving bounds");auto begin=std::chrono::steady_clock::now();uint32_t seed=q.seed?q.seed:uint32_t(std::chrono::high_resolution_clock::now().time_since_epoch().count());SolveResult first;solver::One best;int bestAttempt=-1;int threads=q.multiThreaded?std::max(1u,std::min(8u,std::thread::hardware_concurrency())):1;
 for(int base=0;base<std::clamp(q.iterations,1,100);base+=threads){if(q.cancel&&q.cancel->load()){first.failStage="cancelled";break;}if(std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count()>15){first.failStage="build time budget exceeded";break;}int count=std::min(threads,q.iterations-base);std::vector<std::future<solver::One>> jobs;std::vector<solver::One> results;for(int j=0;j<count;j++){uint32_t ss=uint32_t(hash64(seed,base+j));if(threads>1)jobs.push_back(std::async(std::launch::async,[&q,ss]{return solver::attempt(q,ss);}));else results.push_back(solver::attempt(q,ss));}for(auto& f:jobs)results.push_back(f.get());for(int j=0;j<count;j++){auto& one=results[j];if(first.failStage.empty()&&!one.success)first=one.info;if(!one.success)continue;if(bestAttempt<0||one.info.quality.coverage>best.info.quality.coverage){best=one;bestAttempt=base+j;}if(one.info.accepted){*q.level=std::move(one.level);auto result=one.info;result.iterationsUsed=base+j+1;result.seedUsed=seed;result.ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();if(q.progress)q.progress->store(1);return result;}}}
 if(bestAttempt>=0&&!(q.cancel&&q.cancel->load())){*q.level=std::move(best.level);auto result=best.info;result.iterationsUsed=bestAttempt+1;result.seedUsed=seed;result.message="quality target not met (coverage "+std::to_string(result.quality.coverage*100)+"%, floors "+std::to_string(result.quality.floors)+"/"+std::to_string(q.level->size.z)+")";result.ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();return result;}first.iterationsUsed=0;first.seedUsed=seed;first.ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();return first;
}
}
